-- c005-v007: Menjawab kepada–Nya – orang–sakit, Tuan, manusia tidak aku–punya, supaya ketika diaduk – air, melemparkan aku ke – kolam; sementara lalu namun aku–datang aku, lain sebelum aku turun.
