-- c005-v011: Yang namun menjawab kepada–mereka, Yang menjadikan aku sembuh, Dia kepadaku berkata, Angkatlah – tikar mu dan berjalanlah.
-- c005-v012: Mereka–bertanya <maka> kepadanya, Siapa adalah – orang – yang–berkata kepadamu, Angkatlah dan berjalanlah?
